export type TicketField = { id: string; label: string; placeholder?: string };
export type TicketType = { id: string; label: string; summary: string; minHours: number; linkLabel: string; linkRequired: boolean; fields: TicketField[] };
export type TicketPriority = 'normal' | 'alta';
export type Ticket = {
  id: string;
  type: string;
  typeLabel: string;
  title: string;
  description: string;
  links: string[];
  details: Record<string, string>;
  priority: TicketPriority;
  dueDate: string;
  minHours: number;
  businessHours: number;
  requesterName: string;
  requesterEmail: string;
  createdAt: string;
};
export type TicketInput = Partial<Omit<Ticket, 'links'>> & { links?: string[] | string };

